async function forgetRemoteLink(eventId,provider){
 const e=db.events.find(x=>x.id===eventId),link=e?.externalLinks?.[provider];if(!e||!link)return;
 if(!connector()?.isConnected(provider)){toast('Reconnect to remove this event from the external calendar.');return;}
 if(!confirm('Remove this published event from '+providerTitle(provider)+'?'))return;
 try{await connector().removeRemote(provider,link.calendarId,link.remoteId);update(()=>{delete e.externalLinks[provider];},'External event removed.');}catch(err){toast('Could not remove external event: '+err.message);}
}
async function connectProvider(provider){
 const config=db.connections[provider];if(calendarBusy)return;
 try{connector().assertId(provider,config.clientId);calendarBusy=provider;render();
  if(provider==='outlook'){await connector().microsoftStart(config.clientId);return;}
  await connector().googleConnect(config.clientId);await syncProvider(provider);
 }catch(err){console.error('Connection failed',err);toast(err.message||'Connection failed.');}finally{calendarBusy='';render();}
}
async function syncProvider(provider){
 if(!connector()?.isConnected(provider)){toast('Please connect '+providerTitle(provider)+' first.');return;}
 try{calendarBusy=provider;render();const result=await (provider==='google'?connector().googleLoad():connector().outlookLoad());
  const old=db.connections[provider].calendars||[],failed=new Set(result.failures.map(x=>x.calendarId));
  update(()=>{
   db.connections[provider].calendars=result.calendars.map(c=>({...c,visible:old.find(x=>x.id===c.id)?.visible!==false}));
   const good=new Set(result.calendars.filter(c=>!failed.has(c.id)).map(c=>c.id)),available=new Set(result.calendars.map(c=>c.id));
   db.events=db.events.filter(e=>e.source!==provider||(!good.has(e.calendarId)&&available.has(e.calendarId)));
   const unique=new Set();for(const e of result.events){if(!good.has(e.calendarId)||externalEventMatchesLink(e))continue;const k=e.calendarId+'|'+e.externalId;if(unique.has(k))continue;unique.add(k);db.events.push({id:'external_'+provider+'_'+e.calendarId+'_'+e.externalId,...e});}
   db.connections[provider].lastSync=new Date().toISOString();db.connections[provider].error=result.failures.map(x=>x.message).join(' · ').slice(0,500);
  },result.failures.length?`Synced ${providerTitle(provider)} with ${result.failures.length} calendar warning(s).`:`${providerTitle(provider)} calendar is up to date.`);
 }catch(err){console.error('Calendar sync failed',err);db.connections[provider].error=String(err.message||err).slice(0,500);persist();toast('Could not sync '+providerTitle(provider)+': '+err.message);}finally{calendarBusy='';render();}
}
function disconnectProvider(provider){
 if(!confirm(`Disconnect ${providerTitle(provider)} from MODO? You can also remove its cached events.`))return;
 const clear=confirm('Remove locally cached events from this provider too?');connector()?.disconnect(provider);
 update(()=>{if(clear)db.events=db.events.filter(e=>e.source!==provider);},'Disconnected. Cached events '+(clear?'removed.':'kept for offline viewing.'));
}
function expandICS(raw){
 const expanded=[];const start=addDays(today(),-120),end=addDays(today(),370),weekdays=['SU','MO','TU','WE','TH','FR','SA'];
 for(const event of raw){
  const r=event.rrule;if(!r){if(event.date>=start&&event.date<=end)expanded.push({...event,externalId:(event.externalUid||event.title+'|'+event.date)+'|'+event.date});continue;}
  const rules=Object.fromEntries(r.split(';').map(x=>x.split('=')));const freq=rules.FREQ,interval=Math.max(1,Math.min(365,Number(rules.INTERVAL)||1)),count=Math.min(2000,Number(rules.COUNT)||2000),until=rules.UNTIL?decodeICSDate(rules.UNTIL).date:end,days=(rules.BYDAY||'').split(',').filter(Boolean);let issued=0;
  for(let j=0;j<2200;j++){
   const d=addDays(event.date,j);if(d>until||d>end)break;
   const delta=j;let valid=false;
   if(freq==='DAILY')valid=delta%interval===0;
   else if(freq==='WEEKLY'){const week=Math.floor(delta/7);const dow=weekdays[parseDate(d).getDay()];valid=week%interval===0&&(days.length?days.includes(dow):parseDate(d).getDay()===parseDate(event.date).getDay());}
   else if(freq==='MONTHLY'){const a=parseDate(event.date),b=parseDate(d);valid=((b.getFullYear()-a.getFullYear())*12+(b.getMonth()-a.getMonth()))%interval===0&&b.getDate()===a.getDate();}
   else valid=j===0;
   if(!valid)continue;issued++;if(issued>count)break;
   if(d<start||event.exdates?.includes(d))continue;
   expanded.push({...event,date:d,externalId:(event.externalUid||event.title)+'|'+d});if(expanded.length>=2500)break;
  }
  if(expanded.length>=2500)break;
 }
 return expanded.slice(0,2500);
}
async function syncIcloud(feedId){
 const feed=db.connections.icloud.feeds.find(x=>x.id===feedId);if(!feed)return;
 try{calendarBusy='icloud';render();const content=await connector().appleFetch(feed.url),raw=parseICS(content),data=expandICS(raw);
  update(()=>{db.events=db.events.filter(e=>!(e.source==='icloud'&&e.calendarId===feed.id));
   const seen=new Set();for(const e of data){const k=e.externalId;if(seen.has(k))continue;seen.add(k);db.events.push({...e,id:'icloud_'+feed.id+'_'+k,source:'icloud',calendarId:feed.id,calendarName:feed.name,readonly:true});}
   feed.lastSync=new Date().toISOString();feed.error='';},`Updated ${feed.name}: ${data.length} events.`);
 }catch(err){feed.error=String(err.message||err);persist();toast(feed.error);}finally{calendarBusy='';render();}
}
async function subscribeIcloud(name,url){
 const goodUrl=connector().normalizeAppleUrl(url);
 const entry={id:uid('feed'),name:String(name||'My iCloud calendar').trim().slice(0,90),url:goodUrl,lastSync:'',visible:true,error:''};
 update(()=>{db.connections.icloud.feeds.push(entry);},'Public iCloud subscription saved.');await syncIcloud(entry.id);
}
