function openModal(kind,id=null){ui.modal={kind,id};ui.draft=null;if(kind==='mode'){
 const existing=db.modes.find(x=>x.id===id);ui.draft={base:existing?{title:existing.title,description:existing.description,duration:existing.duration,startDate:existing.startDate,policy:existing.policy}:{title:'',description:'',duration:75,startDate:today(),policy:'flexible'},rules:existing?structuredClone(existing.rules).map(r=>({...r,kind:r.kind==='check'?'check':'amount'})):[{id:uid('rule'),title:'Move your body',kind:'amount',target:45,unit:'minutes',ritualId:''},{id:uid('rule'),title:'Vitamins',kind:'check',target:1,unit:'',ritualId:''}]};
 }render();setTimeout(()=>document.querySelector('.dialog input:not([type="hidden"])')?.focus(),20);}
function closeModal(){ui.modal=null;ui.draft=null;render();}
function dayTaskDone(task,d){return Array.isArray(task.completedDates)&&task.completedDates.includes(d);}
function taskOccurs(task,d){
 if(!task.dueDate)return false;if(d<task.dueDate)return false;
 if(task.repeat==='none')return d===task.dueDate;
 if(task.repeat==='daily')return true;
 const weekday=parseDate(d).getDay(),anchor=parseDate(task.dueDate).getDay();
 if(task.repeat==='weekdays')return weekday>0&&weekday<6;
 if(task.repeat==='weekly')return weekday===anchor;
 if(task.repeat==='monthly')return parseDate(d).getDate()===parseDate(task.dueDate).getDate();
 return false;
}
function tasksOn(d){return db.tasks.filter(t=>taskOccurs(t,d));}
function todayTasks(){const d=today();return db.tasks.filter(t=>taskOccurs(t,d)||(t.repeat==='none'&&t.dueDate&&t.dueDate<d&&!dayTaskDone(t,t.dueDate))).sort((a,b)=>({high:0,medium:1,low:2}[a.priority]??1)-({high:0,medium:1,low:2}[b.priority]??1));}
function taskDateForAction(t,d){return t.repeat==='none'?(t.dueDate||d):d;}
function modeStartEnd(mode){return {start:mode.startDate,end:addDays(mode.startDate,mode.duration-1)};}
function modeElapsed(mode){return Math.max(0,Math.min(mode.duration,diffDays(today(),mode.startDate)+1));}
function getRitualLog(rid,d){return Number(db.rituals.find(r=>r.id===rid)?.logs?.[d]||0);}
function ruleIsCheck(rule){return rule?.kind==='check';}
function modeValue(mode,rule,d){return rule.ritualId?getRitualLog(rule.ritualId,d):Number(mode.logs?.[`${d}|${rule.id}`]||0);}
function modeRuleDone(mode,rule,d){return modeValue(mode,rule,d)>=(ruleIsCheck(rule)?1:Number(rule.target||1));}
function effectiveModeStatus(m){return m.status==='active'&&today()>modeStartEnd(m).end?'completed':m.status;}
function activeMode(){return db.modes.find(m=>effectiveModeStatus(m)==='active')||null;}
function modeDailyProgress(mode,d){const done=mode.rules.filter(r=>modeRuleDone(mode,r,d)).length;return {done,total:mode.rules.length};}
function ritualTodayDone(r,d){return Number(r.logs?.[d]||0)>=Number(r.target||1);}
function ritualOccurs(r,d){const wd=parseDate(d).getDay();return r.schedule!=='weekdays'||(wd!==0&&wd!==6);}
function meetupsForPerson(personId){return db.meetups.filter(m=>m.personId===personId).sort((a,b)=>(b.date||'').localeCompare(a.date||''));}
function allEventsForDate(d){
 let x=db.events.filter(e=>e.date===d && (!isRemoteEvent(e) || connectionVisible(e.source,e.calendarId))).map(e=>({...e,type:'event'}));
 x.push(...tasksOn(d).map(t=>({id:t.id,title:t.title,date:d,time:t.dueTime||'',source:'task',type:'task',linkedId:t.id,done:dayTaskDone(t,taskDateForAction(t,d))})));
 x.push(...db.mealPlans.filter(m=>m.date===d).map(m=>({id:m.id,title:`${m.mealType}: ${db.recipes.find(r=>r.id===m.recipeId)?.name||'Meal'}`,date:d,time:m.time||'',source:'meal',type:'meal',linkedId:m.id})));
 return x.sort((a,b)=>(a.time||'23:59').localeCompare(b.time||'23:59'));
}
function dayItems(d,source='all'){return allEventsForDate(d).filter(e=>source==='all'||(source==='modo'?!isRemoteEvent(e):source==='imported'?isRemoteEvent(e):e.source===source));}
function localAlerts(){const d=today(),now=timeNow(), upcoming=[];
 for(const t of todayTasks()){const key=taskDateForAction(t,d);if(!dayTaskDone(t,key))upcoming.push({id:`task-${t.id}`,title:t.title,sub:t.dueTime?`Task · ${fmtTime(t.dueTime)}${t.dueTime<now?' · Due':' '}`:'Task · Today',date:d,kind:'task'});}
 for(const m of db.meetups.filter(m=>m.status==='scheduled'&&m.date>=d&&m.date<=addDays(d,7)))upcoming.push({id:`meet-${m.id}`,title:m.title,sub:`Meetup · ${fmtDate(m.date)} at ${fmtTime(m.time)}`,date:m.date,kind:'meetup'});
 for(const p of db.people.filter(p=>p.followUp&&p.followUp>=d&&p.followUp<=addDays(d,7)))upcoming.push({id:`follow-${p.id}`,title:`Reconnect with ${p.name}`,sub:`People · ${fmtDate(p.followUp)}`,date:p.followUp,kind:'meetup'});
 return upcoming.slice(0,12);
}
function activityForDate(d){
 const names=[];
 for(const t of db.tasks){if((t.completedDates||[]).includes(d))names.push(`Task: ${t.title}`);}
 for(const r of db.rituals){if(ritualTodayDone(r,d))names.push(`Ritual: ${r.name}`);}
 for(const m of db.modes){for(const rule of m.rules){if(rule.ritualId)continue;if(modeRuleDone(m,rule,d))names.push(`${m.title}: ${rule.title}`);}}
 for(const meet of db.meetups){if(meet.status==='completed'&&meet.date===d)names.push(`Met: ${db.people.find(p=>p.id===meet.personId)?.name||'Someone'}`);}
 for(const recipe of db.recipes){if((recipe.cookedDates||[]).includes(d))names.push(`Cooked: ${recipe.name}`);}
 return names;
}
function sampleBanner(){return `<span class="demo-tag" title="Your workspace is saved to your private account"><i class="dot"></i> Your private space</span>`;}
function progressRing(percent,dark=false,size=98){const r=37,c=2*Math.PI*r;return `<div class="progress-ring" style="width:${size}px;height:${size}px"><svg viewBox="0 0 100 100" role="img" aria-label="${percent}% progress"><circle cx="50" cy="50" r="${r}" fill="none" stroke="${dark?'#59654D':'var(--surface-muted)'}" stroke-width="7"/><circle cx="50" cy="50" r="${r}" fill="none" stroke="${dark?'#D0DCBF':'var(--brand)'}" stroke-width="7" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${c*(1-percent/100)}" transform="rotate(-90 50 50)" /></svg><strong style="color:${dark?'#F3EBDD':'var(--text)'}">${percent}%</strong></div>`;}
