 `<div class="grid-two"><div class="stack">${m?`<div class="card-olive"><div class="eyebrow">MY CURRENT MODE</div><div class="spread" style="position:relative;z-index:1;align-items:center;gap:15px"><div style="flex:1"><h2>${esc(m.title)}</h2><p>${esc(m.description||'Your goals. Your rules.')}</p><div style="margin-top:17px"><div class="spread" style="font-size:11px;color:#D9DFC9;margin-bottom:8px"><span>Day ${modeElapsed(m)} of ${m.duration}</span><span>${Math.max(0,m.duration-modeElapsed(m))} days remaining</span></div><div class="progress"><span style="width:${elapsed}%"></span></div></div></div>${progressRing(elapsed,true,92)}</div><div class="spread" style="position:relative;z-index:1;margin-top:20px"><span style="color:#DDE4D2;font-size:11px">${modeProgress.done}/${modeProgress.total} commitments completed today</span><button class="button small" style="background:#64745D;color:#FFF;border:0" data-nav="modes">Open my mode ${icon('arrowRight',14)}</button></div></div>`:`<div class="card-olive"><div class="eyebrow">MY CURRENT MODE</div><h2>Your next chapter starts here.</h2><p>Create a challenge that fits your life.</p><div style="margin-top:20px">${btn('Create my mode','open-mode','soft')}</div></div>`}
 <div class="card">${sectionTitle("Today's priorities",'All tasks','nav-tasks')}<div>${dayTasks.length?dayTasks.slice(0,5).map(t=>taskRow(t, t.repeat==='none'?t.dueDate:d,true)).join(''):empty('A little room to breathe.','Nothing on today’s task list.','open-task','Add a task')}</div><div class="spread" style="margin-top:14px"><span class="tiny subtle">${dayTasks.filter(t=>dayTaskDone(t,taskDateForAction(t,t.repeat==='none'?t.dueDate:d))).length} of ${dayTasks.length} done</span>${btn(`${icon('plus',15)} Add task`,'open-task','outline','class="small"')}</div></div>
 <div class="card">${sectionTitle('On your calendar','Open calendar','nav-calendar')}<div>${events.length?events.map(eventRow).join(''):empty('An open agenda.','No events planned for today or tomorrow.')}</div></div></div>
 <div class="stack"><div class="card">${sectionTitle('Daily rituals','View rituals','nav-rituals')}<div class="spread" style="margin-bottom:15px"><div><strong class="big-stat">${doneRituals}<span style="font-size:16px;color:var(--text-muted)">/${dueRituals.length}</span></strong><div class="tiny subtle">Done today</div></div>${progressRing(pct(doneRituals,dueRituals.length),false,70)}</div><div>${dueRituals.slice(0,5).map(r=>ritualRow(r,d,true)).join('')||empty('Start small.','Add a ritual for today.')}</div></div>
 <div class="card">${sectionTitle('Make time for people','People','nav-people')}${meet?`<div class="spread" style="align-items:start"><div class="person-avatar">${esc(initials(db.people.find(p=>p.id===meet.personId)?.name))}</div><span class="pill success">Upcoming</span></div><h3 style="margin:14px 0 4px;font-size:15px">${esc(meet.title)}</h3><div class="info-row">${icon('calendar',15)} ${fmtDate(meet.date)} at ${fmtTime(meet.time)}</div>${meet.location?`<div class="info-row" style="margin-top:7px">${icon('pin',15)} ${esc(meet.location)}</div>`:''}<button class="button button-soft small" style="margin-top:14px" data-action="open-meetup" data-id="${esc(meet.id)}">View meetup ${icon('arrowRight',13)}</button>`:empty('Connection matters.','Keep a list of people you want to see.','open-person','Add a person')}</div>
 <div class="card">${sectionTitle('On the menu','My kitchen','nav-meals')}${meal?`<div class="spread"><div class="leading-icon">${icon('meals',19)}</div><span class="pill">${esc(meal.mealType)}</span></div><h3 style="font-size:15px;margin:13px 0 3px">${esc(db.recipes.find(x=>x.id===meal.recipeId)?.name||'Planned meal')}</h3><p class="small-text subtle" style="margin:0">${meal.date===d?'Today':'Tomorrow'}${meal.time?' · '+fmtTime(meal.time):''}</p>`:empty('What are we cooking?','Plan something lovely for later.','open-mealplan','Plan a meal')}</div>
 <div class="callout">${icon('sparkle',19)}<h3>A little reminder</h3><p>Progress isn’t a perfect streak. It’s making room for what matters, whenever you can.</p></div></div></div>`;
