 <div class="filters" role="group" aria-label="Task categories" style="margin-bottom:16px">${cats.map(x=>`<button class="filter ${ui.taskCategory===x?'active':''}" data-action="tasks-category" data-value="${x}">${x}</button>`).join('')}</div>
