 `<input type="file" id="ics-input" accept=".ics,text/calendar" hidden aria-label="Import iCalendar file"><div class="calendar-toolbar" style="margin-bottom:17px"><div class="date-picker-inline"><button class="icon-button tinted" data-action="cal-prev" aria-label="Previous period">${icon('chevronLeft',18)}</button><button class="icon-button tinted" data-action="cal-next" aria-label="Next period">${icon('chevronRight',18)}</button><span class="calendar-title">${title}</span><button class="button button-outline small" data-action="cal-today">Today</button></div><div class="filters">${['month','week','day','agenda'].map(v=>`<button class="filter ${ui.calView===v?'active':''}" data-action="cal-view" data-value="${v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></div><div class="spread" style="margin-bottom:15px;flex-wrap:wrap"><div class="filters">${[['all','All'],['modo','MODO'],['google','Google'],['outlook','Outlook'],['icloud','iCloud'],['meetup','Meetups'],['task','Tasks'],['meal','Meals'],['imported','External']].map(([v,l])=>`<button class="filter ${ui.calSource===v?'active':''}" data-action="cal-source" data-value="${v}">${l}</button>`).join('')}</div><button class="button button-ghost small" data-action="export-ics">${icon('download',15)} Export MODO .ics</button></div>
 <div class="calendar-layout"><div class="card">${ui.calView==='month'?calendarPanel():ui.calView==='week'?calendarWeekPanel():ui.calView==='day'?`<h3 style="margin:0 0 13px">${fmtFull(ui.calDay)}</h3>${selected.length?selected.map(eventRow).join(''):empty('An open day.','Nothing scheduled here yet.')}`:calendarAgendaPanel()}</div><div class="stack"><div class="card"><div class="card-header"><h2>${fmtDate(ui.calDay,{weekday:'long',month:'short',day:'numeric'})}</h2><button class="icon-button" data-action="open-event" title="Add event">${icon('plus',18)}</button></div><div style="margin-top:13px">${selected.length?selected.map(eventRow).join(''):empty('A little breathing room.','No plans on this day.','open-event','Add event')}</div></div><div class="card soft"><div class="spread"><div>${icon('calendar',22)}<h3 style="font-size:14px;margin:10px 0 4px">All your calendars, one view.</h3></div></div><p class="small-text subtle" style="margin:0 0 13px">Connect Google and Outlook via browser sign-in, or subscribe to public Apple/iCloud calendars. Choose which calendars appear.</p>${btn('Manage calendars & accounts','connections','outline')}</div></div></div>`;
