function modeAdherence(m){const elapsed=modeElapsed(m);if(!elapsed||!m.rules.length)return 0;let complete=0,total=0;for(let i=0;i<elapsed;i++){const d=addDays(m.startDate,i);for(const rule of m.rules){const linked=db.rituals.find(r=>r.id===rule.ritualId);if(linked&&!ritualOccurs(linked,d))continue;total++;if(modeRuleDone(m,rule,d))complete++;}}return pct(complete,total);}
